R=Path(__file__).resolve().parents[1];B=R/'artifacts/analog_asic'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def rel(p):return p.relative_to(R).as_posix()
def main():
 old=B/'assembly/article_module_catalog_v66.json';new=B/'assembly/article_module_catalog_v67.json';assert not new.exists();c=json.loads(old.read_text())
