 files=[B/'assembly/full25actor_analog_connectivity_v1.json',B/'assembly/full25actor_permanent_analog_state_selectors_v1.json',B/'assembly/full_capacity_storage_gds_v1/capacity_assembly.json',B/'assembly/full_capacity_storage_gds_v1/full_capacity_storage_v1.gds',B/'results/gf180_full64_rms_frontend_v1_three_native_DC_src0096fb64f3b0.json',B/'layout/gf180_full64_rms_frontend_v1/qualification.json',B/'layout/gf180_full64_rms_frontend_v1/abstract_qualification.json']
 atlas=json.loads(files[2].read_text());assert atlas['logical_active_analog_nodes']==54630400 and atlas['physical_bank_instances']==866080
 review=B/'results/gf180_full64_flat_and_storage_atlas_method_review_v1.json';assert not review.exists()
 review.write_text(json.dumps(dict(method_review_completed=True,full64_native_source_GDS_LEF_complete=True,full64_native_three_DC_cases_complete=True,full64_geometric_flat_DRC_count=0,full64_geometric_flat_extraction_complete=False,
  full64_finding='Initial1800s full-flat operation completed DRC0 but timed out while extraction remained incomplete. Focused extraction-only120s attempt also incomplete. Preserve both EXT files; neither is accepted. Algebraic hierarchical capacitance expansion being compared against independent completed flat baseline; no further geometric/runtime sweep.',
  storage_atlas_native_GDS_read_completed=False,storage_atlas_finding='Independent binary GDS readback resolves all hierarchy references and exact bank capacity. One2GB native Magic read aborted while reading first state plane before bbox/output; no completed native whole-atlas DRC/LVS or read qualification. Preserve qualified bank GDS and do not expand54m states to obtain local module evidence.',
  full_chip_layout_complete=False,original_float_accuracy_accepted=False,full_5ms_population_service_accepted=False),indent=2)+'\n');files.append(review)
 for e in c.get('in_progress_assemblies',[]):
  if e['cell']=='gf180_full64_rms_frontend_v1':e.update(source_GDS_LEF_complete=True,source_GDS_flat_LEF_complete=False,native_three_DC_cases_complete=True,geometric_flat_DRC_count=0,geometric_flat_extraction_complete=False,method_review=rel(review),scope='2397MOS physically joined full64 RMS/frontend source/GDS exact-graph qualification and LEF complete; three native connected DC points complete. Flat RC extraction/transient remain unfinished; no complete transient count.')
 c.update(revision=67,previous_catalog=rel(old),full25_graph=rel(files[0]),permanent_analog_state_selectors=rel(files[1]),storage_only_capacity_layout=rel(files[2]),full_chip_layout_complete=False)
 c['sha256'].update({rel(p):sha(p) for p in files});new.write_text(json.dumps(c,indent=2)+'\n')
 docs=[R/'docs'/n for n in ['AGENTS.md','ACTIVE_TASKS.md','ARCHITECTURE.md','DECISIONS.md','RESULTS.md','PROGRESS.md','project_spec.yaml']];stamp=datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%dT%H%M%SZ');zp=B/'documentation_history'/('project_docs_before_dense_storage_assembly_'+stamp+'.zip')
 with zipfile.ZipFile(zp,'x',zipfile.ZIP_DEFLATED) as z:
  for p in docs:z.writestr(rel(p),p.read_bytes())
 zp.with_suffix('.json').write_text(json.dumps({'archive_sha256':sha(zp),'files':{rel(p):sha(p) for p in docs}},indent=2)+'\n')
 texts={
 'RESULTS.md':'The compact4T/50fF cell, actual2x2 bank and actual8x8 bank complete native source/GDS fullDRC0, independent reference LVS, flat routing capacitance and real LEF. All64 states in the8x8 bank complete selective overwrite, stressed5ms hold and two-row read: maximum write error1.43mV, hold excursion10.64mV and selected-read disturbance4.89mV. Read offsets and external ideal drivers remain. Catalog67 has20 reusable modules/50 completed characterization assemblies. Full64 RMS/frontend source/GDS/LEF and three native DC points separately complete; flatRC/transient remain incomplete.',
 'ARCHITECTURE.md':'The original float graph is43nodes54edges with25PLIF actors and23serial PLIF stages. Preserve categorical residual clamps, unclipped project2+x1 multiplicity and continuous6class readout. Exact56state-plane selectors cover54,630,400 permanent analog identities. Real8x8 storage routing has18um column/13.5um row pitch and149.42x112.4um bank bbox. Storage grouping does not select64-site compute sharing. A uniform217.39us per actor stage, or3.397us per site if64sites were shared, excludes routing/readout and is only a necessary bound.',
 'DECISIONS.md':'Reuse the completed8x8 storage geometry for a capacity-only layout assembly; do not replicate spacious characterization fixtures as dense neuron area. The GDS atlas contains866,080 native bank instances,55,429,120 slots including798,720 inactive boundary slots, covering every54,630,400 active identity. Bank geometry totals14,545.65mm2 before global routing/compute and is not the earlier1,215mm2 bare-plate estimate. This atlas is not a chosen manufacturable die/stack/chiplet architecture. Do not label it full-chip completion or infer model acceptance. Preserve the unsuccessful native atlas read and geometric full64 extraction; no blind runtime/precision sweep.',
 'PROGRESS.md':'Catalog67 records three newly completed storage characterization assemblies and full-capacity storage-only GDS. Full25 topology and selector construction complete; all-chip computation/interconnect remain incomplete. Native full64 RMS/frontend DC completes; geometric flat extraction and joined transient pending. Prior docs archived exactly at '+rel(zp)+'.'
 }
 for name,text in texts.items():
  p=R/'docs'/name;b=p.read_bytes();i=b.index(b'\n## ');p.write_bytes(b[:i]+('\n## Dense analog storage and assembly milestone - 2026-10-11\n\n'+text+'\n\nEvidence: `artifacts/analog_asic/assembly/article_module_catalog_v67.json`, `artifacts/analog_asic/assembly/full_capacity_storage_gds_v1/capacity_assembly.json`, `artifacts/analog_asic/results/gf180_full64_flat_and_storage_atlas_method_review_v1.json`.\n').encode()+b[i:])
 p=R/'docs/ACTIVE_TASKS.md';b=p.read_bytes().replace(old.name.encode(),new.name.encode()).replace(b'catalog revision66',b'catalog revision67');b=re.sub(rb'\| Job status \|[^\r\n]+',b'| Job status | Three compact storage assemblies completed; full-capacity storage-only GDS written. Full64 hierarchical RC method under validation; complete compute/global interconnect still unfinished. |',b,count=1)
 b=b.replace(b'## Next work package',b'## Assembly milestone\r\n\r\nFull25 graph and permanent selectors constructed; native8x8 bank layout/5ms sequence complete. Storage-only GDS covers54.63million active identities using866,080 real banks. Bank area14,545.65mm2 excludes global routing and computation; earlier1,215mm2 was bare-plate only. This is not full-chip completion. Full64 RMS/frontend source/GDS/LEF and three DC cases complete, with flatRC/transient pending. Next: resolve hierarchical RC validation and connected compute/control assembly; retain measured imperfections.\r\n\r\n## Next work package',1);p.write_bytes(b)
 p=R/'docs/project_spec.yaml';b=p.read_bytes();head,tail=b.split(b'\ndocument:',1);head=head.replace(old.name.encode(),new.name.encode());head=re.sub(rb'  live_sessions: [^\r\n]+',b'  live_sessions: []',head,count=1);head=re.sub(rb'  evidence: [^\r\n]+',b'  evidence: artifacts/analog_asic/assembly/full_capacity_storage_gds_v1/capacity_assembly.json',head,count=1);head=re.sub(rb'    next_action: [^\r\n]+',b'    next_action: validate_hierarchical_RC_then_connected_compute_control_and_global_layout',head,count=1);p.write_bytes(head+b'\ndocument:'+tail)
 print(new);print(zp)
